solutionCode:
function statusMessage(state) {
  const messages = {
    loading: 'Loading results…',
    success: 'Results are ready.',
    empty: 'No results found. Try another search.',
    error: 'Could not load results. Please try again.'
  };
  return messages[state] || 'Ready.';
}

['loading', 'success', 'empty', 'error'].forEach(state => console.log(statusMessage(state)));

