solutionCode:
function cacheLifetime(resource) {
  if (resource.type === 'asset' && resource.hashed) return 31536000;
  if (resource.type === 'html') return 0;
  return 300;
}

console.log(cacheLifetime({ type: 'asset', hashed: true }));
console.log(cacheLifetime({ type: 'html' }));

